const DISMISSED='family-budget:dismissed-recurring';
function readDismissed():string[]{try{return JSON.parse(localStorage.getItem(DISMISSED)||'[]')}catch{return []}}
function RecurringSuggestions({settings:s}:{settings:Settings}){
 const list=useQuery({queryKey:['recurring-suggestions'],queryFn:()=>api<RecurringSuggestion[]>('/recurring/suggestions')});
 const [dismissed,setDismissed]=useState(readDismissed);
 const dismiss=(m:string)=>{const next=[...dismissed,m];setDismissed(next);try{localStorage.setItem(DISMISSED,JSON.stringify(next))}catch{/* stays hidden until reload */}};
 const shown=(list.data||[]).filter(x=>!dismissed.includes(x.merchant));
 if(!shown.length)return <ErrorBox error={list.error}/>;
 return <div className="suggestions"><h3>הצעות מההיסטוריה ({shown.length})</h3><p className="subtext">חיובים שחזרו בסכום דומה בכמה חודשים. הוסיפו את מה שבאמת קבוע; „לא קבועה” מסתירה את ההצעה.</p>{shown.map(x=><SuggestionRow key={x.merchant} item={x} categories={s.categories} onDismiss={()=>dismiss(x.merchant)}/>)}</div>
}
function SuggestionRow({item:x,categories,onDismiss}:{item:RecurringSuggestion;categories:Settings['categories'];onDismiss:()=>void}){
 const [name,setName]=useState(x.merchant),[category,setCategory]=useState(x.category_id||''),[expected,setExpected]=useState(x.expected),[day,setDay]=useState(String(x.day_of_month));const client=useQueryClient();
 const save=useMutation({mutationFn:()=>send('/recurring',{name,merchant:x.merchant,category_id:category,expected,day_of_month:Number(day)}),onSuccess:()=>client.invalidateQueries()});
 return <form className="list-row suggestion-row" onSubmit={e=>{e.preventDefault();save.mutate()}}><div><strong><bdi>{x.merchant}</bdi></strong><small>{x.source==='bank'?'בנק':'כרטיס'} · {x.months.map(m=>hebMonth(m).split(' ')[0]).join(', ')}</small></div><label className="field"><span>שם</span><input value={name} onChange={e=>setName(e.target.value)} required/></label><Select label="קטגוריה" value={category} onChange={setCategory} options={categories.filter(c=>c.kind!=='income')} empty="בחרו"/><label className="field"><span>סכום ₪</span><input dir="ltr" value={expected} onChange={e=>setExpected(e.target.value)} required/></label><label className="field"><span>יום</span><input type="number" min="1" max="28" value={day} onChange={e=>setDay(e.target.value)} required/></label><button className="secondary" disabled={save.isPending||!category}><Plus size={15}/>הוספה</button><button type="button" className="text-button" onClick={onDismiss}>לא קבועה</button><ErrorBox error={save.error}/></form>
}

function RecurringRow({item:r,categories}:{item:Settings['recurring'][number];categories:Settings['categories']}){
 const [editing,setEditing]=useState(false),[name,setName]=useState(r.name),[category,setCategory]=useState(r.category_id),[expected,setExpected]=useState(r.expected),[day,setDay]=useState(String(r.day_of_month)),[active,setActive]=useState(r.active),[merchant,setMerchant]=useState(r.merchant||'');
 const client=useQueryClient();
 const save=useMutation({mutationFn:()=>send('/recurring/'+r.id,{name,merchant:merchant||null,category_id:category,expected,day_of_month:Number(day),active},'PUT'),onSuccess:()=>{setEditing(false);client.invalidateQueries()}});
 const remove=useMutation({mutationFn:()=>api('/recurring/'+r.id,{method:'DELETE'}),onSuccess:()=>client.invalidateQueries()});
 if(editing)return <form className="list-row" onSubmit={e=>{e.preventDefault();save.mutate()}}><label className="field"><span>שם</span><input value={name} onChange={e=>setName(e.target.value)} required/></label><label className="field"><span>שם בתנועה (לזיהוי)</span><input value={merchant} onChange={e=>setMerchant(e.target.value)}/></label><Select label="קטגוריה" value={category} onChange={setCategory} options={categories}/><label className="field"><span>סכום צפוי ₪</span><input dir="ltr" value={expected} onChange={e=>setExpected(e.target.value)} required/></label><label className="field"><span>יום בחודש (1–28)</span><input type="number" min="1" max="28" value={day} onChange={e=>setDay(e.target.value)} required/></label><label className="check-label"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/>פעילה</label><button className="secondary" disabled={save.isPending||!category}>שמירה</button><button type="button" className="text-button" onClick={()=>{setEditing(false);setName(r.name);setCategory(r.category_id);setExpected(r.expected);setDay(String(r.day_of_month));setActive(r.active);setMerchant(r.merchant||'')}}>ביטול</button><ErrorBox error={save.error}/></form>;
 return <div className="list-row"><strong>{r.name}</strong><span>ביום {r.day_of_month} בחודש{r.active?'':' · מושבתת'} · {r.merchant?<bdi>{r.merchant}</bdi>:<em>בלי שם בתנועה — לא יזוהה</em>}</span><Money value={r.expected}/><span className="row-actions"><button className="text-button" onClick={()=>setEditing(true)}>עריכה</button><button className="text-button danger" disabled={remove.isPending} onClick={()=>{if(window.confirm(`למחוק את ההוצאה הקבועה ${r.name}?`))remove.mutate()}}>מחיקה</button></span><ErrorBox error={remove.error}/></div>
}

function LoanEditor({item}:{item:Settings['loans'][number]}){
 const client=useQueryClient();const [principal,setPrincipal]=useState(item.principal||''),[monthly,setMonthly]=useState(item.monthly_payment),[tx,setTx]=useState(''),[paidPrincipal,setPaidPrincipal]=useState(''),[interest,setInterest]=useState(''),[editing,setEditing]=useState('');
 const payments=useQuery({queryKey:['loan-payments',item.id],queryFn:()=>api<{id:string;transaction_id:string;principal:string;interest:string}[]>('/loans/'+item.id+'/payments')});
 const save=useMutation({mutationFn:()=>send('/loans/'+item.id,{name:item.name,principal:principal||null,monthly_payment:monthly},'PUT'),onSuccess:()=>client.invalidateQueries()});
 const record=useMutation({mutationFn:()=>send('/loans/'+item.id+'/payments'+(editing?'/'+editing:''),{transaction_id:tx,principal:paidPrincipal,interest},editing?'PUT':'POST'),onSuccess:()=>{client.invalidateQueries();setEditing('');setTx('');setPaidPrincipal('');setInterest('')}});
 return <div className="loan-editor"><h3>{item.name}</h3><ErrorBox error={save.error||record.error||payments.error}/><form className="inline-form" onSubmit={e=>{e.preventDefault();save.mutate()}}><label className="field"><span>קרן פתיחה מאומתת ₪ (רשות)</span><input dir="ltr" value={principal} onChange={e=>setPrincipal(e.target.value)}/></label><label className="field"><span>תשלום חודשי מתוכנן ₪</span><input dir="ltr" value={monthly} onChange={e=>setMonthly(e.target.value)} required/></label><button className="secondary" disabled={save.isPending}>שמירת פרטי הלוואה</button></form><details><summary>פירוט תשלומים — קרן וריבית</summary><p className="fine-print">קשרו תשלום שהוגדר ואושר כהלוואה או משכנתא. הפירוט אינו יוצר חיוב נוסף.</p>{payments.data?.map(p=><div className="list-row" key={p.id}><span>קרן <Money value={p.principal}/></span><span>ריבית <Money value={p.interest}/></span><button className="text-button" onClick={()=>{setEditing(p.id);setTx(p.transaction_id);setPaidPrincipal(p.principal);setInterest(p.interest)}}>תיקון הפירוט</button></div>)}<form className="inline-form" onSubmit={e=>{e.preventDefault();record.mutate()}}><label className="field"><span>מזהה תנועת התשלום</span><input dir="ltr" value={tx} onChange={e=>setTx(e.target.value)} required/></label><label className="field"><span>קרן ₪</span><input dir="ltr" value={paidPrincipal} onChange={e=>setPaidPrincipal(e.target.value)} required/></label><label className="field"><span>ריבית ₪</span><input dir="ltr" value={interest} onChange={e=>setInterest(e.target.value)} required/></label><button className="secondary" disabled={record.isPending}>{editing?'שמירת תיקון':'קישור תשלום'}</button></form></details></div>
}
